style.css:
body {
    background-color: #1a1a1a; /* Dark background, similar to Gemini's dark mode */
    color: #f0f0f0; /* White/off-white text */
    font-family: 'Roboto', 'Arial', sans-serif; /* Sans-serif font, Roboto is a good, clean choice */
    line-height: 1.6; /* Improve readability */
    margin: 0;
    padding: 20px; /* Add some padding around the content */
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
    color: #e0e0e0; /* Slightly lighter white for headings */
    font-family: 'Google Sans', 'Roboto', sans-serif; /* Google Sans if available, otherwise Roboto */
    margin-top: 1.5em;
    margin-bottom: 0.8em;
}

h1 {
    font-size: 2.5em;
}

h2 {
    font-size: 2em;
}

/* Links */
a {
    color: #8ab4f8; /* A light blue, similar to Gemini's link color */
    text-decoration: none; /* No underline by default */
}

a:hover {
    text-decoration: underline; /* Underline on hover for better usability */
}

/* Paragraphs */
p {
    margin-bottom: 1em;
}

/* Code blocks */
pre {
    background-color: #2b2b2b; /* Slightly lighter dark background for code */
    color: #c0c0c0; /* Lighter text for code */
    padding: 15px;
    border-radius: 5px;
    overflow-x: auto; /* Enable horizontal scrolling for long code lines */
    font-family: 'Fira Code', 'Roboto Mono', monospace; /* Monospaced font for code */
    font-size: 0.95em;
}

code {
    font-family: 'Fira Code', 'Roboto Mono', monospace;
    background-color: #2b2b2b;
    padding: 2px 5px;
    border-radius: 3px;
}

/* Blockquotes */
blockquote {
    border-left: 4px solid #8ab4f8; /* Blue border for quotes */
    padding-left: 15px;
    margin-left: 0;
    color: #b0b0b0; /* Slightly darker text for quotes */
    font-style: italic;
}

/* Lists */
ul, ol {
    margin-bottom: 1em;
    padding-left: 25px;
}

li {
    margin-bottom: 0.5em;
}

/* Tables */
table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 1em;
}

th, td {
    border: 1px solid #3a3a3a; /* Darker border for tables */
    padding: 8px;
    text-align: left;
}

th {
    background-color: #2b2b2b;
    color: #e0e0e0;
}

/* Forms (basic styling) */
input[type="text"],
input[type="email"],
input[type="password"],
textarea {
    background-color: #2b2b2b;
    color: #f0f0f0;
    border: 1px solid #444;
    padding: 10px;
    border-radius: 5px;
    width: 100%;
    box-sizing: border-box; /* Include padding and border in the element's total width and height */
    margin-bottom: 10px;
}

input[type="submit"],
button {
    background-color: #8ab4f8;
    color: #1a1a1a;
    border: none;
    padding: 10px 20px;
    border-radius: 5px;
    cursor: pointer;
    font-weight: bold;
}

input[type="submit"]:hover,
button:hover {
    background-color: #a7c7ff; /* Slightly lighter blue on hover */
}

/* Scrollbar (for webkit browsers) */
::-webkit-scrollbar {
    width: 10px;
    height: 10px;
}

::-webkit-scrollbar-track {
    background: #2b2b2b;
}

::-webkit-scrollbar-thumb {
    background: #555;
    border-radius: 5px;
}

::-webkit-scrollbar-thumb:hover {
    background: #777;
}

/* General improvements */
*, *:before, *:after {
    box-sizing: inherit;
}
html {
    box-sizing: border-box;
}
